<script setup lang="ts">import {computed} from "vue";import type {GraphNode} from "@/types/graph";import type {ToolCall} from "@/types/toolCall";const props=defineProps<{node?:GraphNode;toolCall?:ToolCall}>();const title=computed(()=>props.node?.type==="user_intent"?"Conversation intent":props.node?.type==="sensitive_object"?"Sensitive object observed":props.node?.type==="blocked"?"Execution prevented":"Pre-execution decision");const decision=computed(()=>props.node?.decision??props.toolCall?.decision??"review");</script>
<template><div v-if="node" class="tab-copy"><span class="decision-badge" :class="decision">{{decision}}</span><h3>{{title}}</h3><p>{{node.detail}}</p><dl><div><dt>Node type</dt><dd>{{node.type}}</dd></div><div><dt>Risk level</dt><dd>{{node.risk}}</dd></div><div><dt>Matched rule</dt><dd>{{node.policyId ?? toolCall?.policyHits.join(', ') ?? 'context evaluation'}}</dd></div><div v-if="toolCall"><dt>Tool latency</dt><dd>{{toolCall.latencyMs}}ms</dd></div></dl></div><div v-else class="empty">Select a path node to inspect its decision.</div></template>
